WebSecurityConfigurerAdapter        ---USUNIETY w 6.0---> bean SecurityFilterChain
authorizeRequests()+antMatchers()   ---deprecated 5.7+---> authorizeHttpRequests()+requestMatchers()
@EnableGlobalMethodSecurity         ---deprecated 6.0----> @EnableMethodSecurity

// NIE SKOMPILUJE SIE na Spring Boot 3.x
class SecurityConfig extends WebSecurityConfigurerAdapter {
    @Override
    protected void configure(HttpSecurity http) throws Exception {
        http.authorizeRequests()
            .antMatchers("/public/**").permitAll()
            .anyRequest().authenticated();
    }
}

@Bean
SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
    http.authorizeHttpRequests(auth -> auth
            .requestMatchers(HttpMethod.GET, "/api/ping").authenticated()
            .anyRequest().denyAll())
        .httpBasic(Customizer.withDefaults());
    return http.build();
}

